create table if not exists public.submissions(id bigint generated by default as identity primary key,kind text not null check(kind in ('question','school')),payload jsonb not null,created_at timestamptz not null default now());
create table if not exists public.impact(key text primary key,value integer not null default 0);
create table if not exists public.admins(user_id uuid primary key references auth.users(id) on delete cascade);
insert into public.impact(key,value) values('schools',0),('students',0),('sessions',0),('volunteers',0) on conflict(key) do nothing;
alter table public.submissions enable row level security;alter table public.impact enable row level security;alter table public.admins enable row level security;
create policy "public can submit" on public.submissions for insert to anon,authenticated with check(true);
create policy "admins can read submissions" on public.submissions for select to authenticated using(exists(select 1 from public.admins a where a.user_id=auth.uid()));
create policy "public can read impact" on public.impact for select to anon,authenticated using(true);
create policy "admins can insert impact" on public.impact for insert to authenticated with check(exists(select 1 from public.admins a where a.user_id=auth.uid()));
create policy "admins can update impact" on public.impact for update to authenticated using(exists(select 1 from public.admins a where a.user_id=auth.uid())) with check(exists(select 1 from public.admins a where a.user_id=auth.uid()));
create policy "admins can read own admin row" on public.admins for select to authenticated using(user_id=auth.uid());
